  1	/**
  2	 * Queue reading internals for the orchestrator run queue (WP-B extraction).
  3	 *
  4	 * Reads `.run-queue.json`, enriches each raw entry with computed lifecycle
  5	 * state and JSONL progress data, and returns the result as `QueueEntry[]`.
  6	 *
  7	 * This module is read-only with respect to the queue file and all other files.
  8	 *
  9	 * The `isRawQueueEntry` type-guard has been extracted to `validate-entry.ts`
 10	 * for direct testability; it is imported here and re-used at the filter call site.
 11	 *
 12	 * Exports beyond `getQueue()`:
 13	 *   - `readQueueFile` — used by `checkNoConflict` in `orchestrator-manager.ts`.
 14	 *   - `isProcessAlive` — used by queue-mutation functions in `orchestrator-manager.ts`.
 15	 *   - `getProjectLedgerStatus` — used by `killQueueEntry`/`dismissQueueEntry`
 16	 *     in `orchestrator-manager.ts`.
 17	 *
 18	 * Ledger path layout — dual-mode (introduced in WP-007):
 19	 *   `getProjectLedgerStatus()` supports two path layouts depending on whether
 20	 *   the queue entry carries an `expectedRepo` (multi-root workspace) value:
 21	 *
 22	 *   • Namespaced (expectedRepo non-null):
 23	 *       `<ledgerRoot>/<expectedRepo>/<slug>/project-ledger.json`
 24	 *   • Flat / legacy (expectedRepo null):
 25	 *       `<ledgerRoot>/<slug>/project-ledger.json`
 26	 *
 27	 *   All three call sites — `getQueue()`, `killQueueEntry()`, and
 28	 *   `dismissQueueEntry()` — pass `entry.expectedRepo` as the third argument,
 29	 *   so the correct layout is selected automatically per entry.
 30	 */
 31	
 32	import { readFile } from 'node:fs/promises';
 33	import { join } from 'node:path';
 34	
 35	import { QUEUE_FILENAME, type RawQueueEntry, type QueueEntry } from './types.js';
 36	import { isRawQueueEntry } from './validate-entry.js';
 37	import { resolveProgress } from './resolve-progress.js';
 38	import { computeEffectiveStatus } from './compute-effective-status.js';
 39	import { assertSafeSegment } from '../../utils/path-validator.js';
 40	
 41	// ---------------------------------------------------------------------------
 42	// PID alive check
 43	// ---------------------------------------------------------------------------
 44	
 45	/**
 46	 * Returns `true` if the process with `pid` exists on this machine.
 47	 *
 48	 * Uses `process.kill(pid, 0)` which is a zero-signal check — it only
 49	 * verifies the process exists and does not actually deliver any signal.
 50	 *
 51	 * Exported for use by queue-mutation functions in `orchestrator-manager.ts`.
 52	 */
 53	export function isProcessAlive(pid: number): boolean {
 54	  try {
 55	    process.kill(pid, 0);
 56	    return true;
 57	  } catch {
 58	    return false;
 59	  }
 60	}
 61	
 62	// ---------------------------------------------------------------------------
 63	// Queue file reader
 64	// ---------------------------------------------------------------------------
 65	
 66	/**
 67	 * Reads and parses `<logsDir>/.run-queue.json`.
 68	 * Returns `[]` on any I/O or parse error — fail-safe.
 69	 * Never writes to the queue file.
 70	 *
 71	 * Exported for use by `checkNoConflict` in `orchestrator-manager.ts`.
 72	 */
 73	export async function readQueueFile(logsDir: string): Promise<RawQueueEntry[]> {
 74	  const queuePath = join(logsDir, QUEUE_FILENAME);
 75	  let raw: string;
 76	  try {
 77	    raw = await readFile(queuePath, 'utf-8');
 78	  } catch {
 79	    return [];
 80	  }
 81	  try {
 82	    const data: unknown = JSON.parse(raw);
 83	    if (!Array.isArray(data)) return [];
 84	    return data.filter(isRawQueueEntry);
 85	  } catch {
 86	    return [];
 87	  }
 88	}
 89	
 90	// ---------------------------------------------------------------------------
 91	// Project ledger check
 92	// ---------------------------------------------------------------------------
 93	
 94	/**
 95	 * Returns whether the project identified by `slug` (and optionally `expectedRepo`)
 96	 * has a ledger entry and whether synthesis has been generated for it.
 97	 *
 98	 * When `expectedRepo` is non-null the function constructs a namespaced path:
 99	 *   `<ledgerRoot>/<expectedRepo>/<slug>/project-ledger.json`
100	 *

101	 * When `expectedRepo` is null it falls back to the legacy flat path for
102	 * backward compatibility with queue entries that pre-date multi-root workspace
103	 * support:
104	 *   `<ledgerRoot>/<slug>/project-ledger.json`
105	 *
106	 * Fail-safe: any I/O or parse error returns `{ exists: false, synthesisGenerated: false }`.
107	 * Defense-in-depth: `slug` and `expectedRepo` (when non-null) are validated with
108	 * `assertSafeSegment()` before any path is constructed. An invalid segment also returns
109	 * `{ exists: false, synthesisGenerated: false }`.
110	 *
111	 * Exported for use by `killQueueEntry`/`dismissQueueEntry` in `orchestrator-manager.ts`.
112	 *
113	 * @param ledgerRoot   - Absolute path to the ledger root directory.
114	 * @param slug         - Project slug (e.g. `2026-05-05-my-feature`).
115	 * @param expectedRepo - Repository name (workspace root slug), or `null` for
116	 *                       legacy flat-path lookup.
117	 * @returns An object with two fields:
118	 *   - `exists` — `true` when the `project-ledger.json` file is present and
119	 *     readable; `false` on any I/O error or when the file does not exist.
120	 *   - `synthesisGenerated` — `true` when the ledger's `synthesis_generated` field equals
121	 *     `true`; `false` when the file is absent, unreadable, or the field is falsy.
122	 */
123	export async function getProjectLedgerStatus(
124	  ledgerRoot: string,
125	  slug: string,
126	  expectedRepo: string | null = null,
127	): Promise<{ exists: boolean; synthesisGenerated: boolean }> {
128	  // Defense-in-depth: reject path segments that would cause traversal or
129	  // produce invalid filesystem paths. assertSafeSegment() allows only
130	  // lowercase alphanumeric-and-hyphen strings starting with [a-z0-9].
131	  if (!assertSafeSegment(slug)) {
132	    return { exists: false, synthesisGenerated: false };
133	  }
134	  if (expectedRepo !== null && !assertSafeSegment(expectedRepo)) {
135	    return { exists: false, synthesisGenerated: false };
136	  }
137	  const projectLedgerPath = expectedRepo
138	    ? join(ledgerRoot, expectedRepo, slug, 'project-ledger.json')
139	    : join(ledgerRoot, slug, 'project-ledger.json');
140	  let raw: string;
141	  try {
142	    raw = await readFile(projectLedgerPath, 'utf-8');
143	  } catch {
144	    return { exists: false, synthesisGenerated: false };
145	  }
146	  try {
147	    const data = JSON.parse(raw) as Record<string, unknown>;
148	    return {
149	      exists: true,
150	      synthesisGenerated: data['synthesis_generated'] === true,
151	    };
152	  } catch {
153	    return { exists: true, synthesisGenerated: false };
154	  }
155	}
156	
157	// ---------------------------------------------------------------------------
158	// Public API
159	// ---------------------------------------------------------------------------
